row(33, 50, 'MATERIAL', f'AND THE LORD SPOKE TO MOSES IN THE PLAINS OF MOAB BY THE JORDAN AT JERICHO, SAYING — THE CHAPTER\'S ONE DIVINE FRAME, THE FORMULA\'S TWO SEATS. {HP(33, 50, (("וידבר", "יהוה", "אל", "משה", "בערבת", "מואב"), "AND THE LORD SPOKE TO MOSES IN THE PLAINS OF MOAB — 33:50 and 35:1 (the Levite cities\' opening), the framed formula\'s two seats; the chapter\'s one frame after forty-nine verses of narrative, one speech follows (33:51-56); ninety-three narrative verbs in forty-seven verses (computed)"), (("על", "ירדן", "ירחו", "לאמר"), "by the Jordan at Jericho, saying"))} → {AP(33, 50, (("ומליל", "יי", "עם", "משה", "במישריא", "דמואב"), "and the LORD spoke with Moses in the plains of Moab"), (("על", "ירדנא", "דירחו", "למימר"), "by the Jordan of Jericho, saying"))}.')
