row(33, 52, 'MATERIAL', f'YOU SHALL DRIVE OUT ALL THE INHABITANTS OF THE LAND FROM BEFORE YOU AND DESTROY ALL THEIR FIGURED STONES, DESTROY ALL THEIR MOLTEN IMAGES AND DEMOLISH ALL THEIR HIGH PLACES — THREE OBJECTS OF ITS OWN, AND LEVITICUS 26\'S CURSE ON THE THIRD. {HP(33, 52, (("והורשתם", "את", "כל", "ישבי", "הארץ", "מפניכם"), "YOU SHALL DRIVE OUT all the inhabitants of the land from before you — one seat; \'the inhabitants of the land\' five Torah seats, Exodus 23:31\'s promise among them (\'I will deliver the inhabitants of the land into your hand and you shall drive them out\') (computed)"), (("ואבדתם", "את", "כל", "משכיתם"), "and destroy all THEIR FIGURED STONES — Leviticus 26:1\'s \'figured stone\' the noun\'s other Torah seat (Psalm 73:7 a plural form) (computed); the store glosses \'and-wander-away\', \'figure\'"), (("ואת", "כל", "צלמי", "מסכתם", "תאבדו"), "and all THEIR MOLTEN IMAGES you shall destroy — one seat; \'molten\' the calf\'s word (Exodus 32:4, 8; Deuteronomy 9:12, 16), Exodus 34:17, Leviticus 19:4, Deuteronomy 27:15 (computed); \'from Succoth\' (Exodus 13:20, 33:6) the consonantal look-alike"), (("ואת", "כל", "במתם", "תשמידו"), "and all THEIR HIGH PLACES you shall DEMOLISH — Leviticus 26:30\'s curse \'I will demolish your high places\', the same verb on the same object: the command and its curse; the verb\'s form two Bible seats (Joshua 7:12); \'their high places\' shares its consonants with \'at their death\' (Leviticus 11:31-32, 6:7), told by the points and the morphology (computed). Exodus 23:24, 34:13, Deuteronomy 7:5 and 12:2-3 name OTHER objects — altars, pillars, asherim, graven images: 33:52\'s three are its own (computed)"))} → {AP(33, 52, (("ותתרכון", "ית", "כל", "יתבי", "ארעא", "מן", "קדמיכון"), "and you shall drive out all the inhabitants of the land from before you"), (("ותבדון", "ית", "כל", "בית", "סגדתהון"), "and destroy all THEIR HOUSES OF WORSHIP — the figured stones read as the places of bowing; the word at 31:10 for Midian\'s encampments (computed)"), (("וית", "כל", "צלמי", "מתכתהון", "תבדון"), "and all the images of their casting you shall destroy"), (("וית", "כל", "במתהון", "תשצון"), "and all their high places you shall demolish"))}.')
row(33, 53, 'MATERIAL', f'AND YOU SHALL POSSESS THE LAND AND DWELL IN IT, FOR TO YOU I HAVE GIVEN THE LAND TO POSSESS IT — ONKELOS SUPPLIES "THE INHABITANTS". {HP(33, 53, (("והורשתם", "את", "הארץ", "וישבתם", "בה"), "and you shall POSSESS THE LAND and dwell in it — \'dwell in it\' Deuteronomy 11:31\'s (computed)"), (("כי", "לכם", "נתתי", "את", "הארץ", "לרשת", "אתה"), "for to you I have given the land TO POSSESS IT — the clause one seat; \'to possess it\' Leviticus 20:24\'s (computed)"))} → {AP(33, 53, (("ותתרכון", "ית", "יתבי", "ארעא"), "and you shall DRIVE OUT THE INHABITANTS OF THE LAND — Onkelos writes \'the inhabitants\' where the Hebrew has \'the land\' as the verb\'s object, reading the possessing as the dispossessing of 33:52 (computed on the tokens)"), (("ותיתבון", "בה", "ארי", "לכון", "יהבית", "ית", "ארעא"), "and dwell in it, for to you I have given the land"), (("למירת", "יתה"), "to inherit it"))}.')
row(33, 54, 'MATERIAL', f'YOU SHALL INHERIT THE LAND BY LOT ACCORDING TO YOUR FAMILIES: TO THE MANY YOU SHALL INCREASE HIS INHERITANCE AND TO THE FEW DIMINISH HIS INHERITANCE; TO WHOM THE LOT GOES OUT, HIS IT SHALL BE; BY THE TRIBES OF YOUR FATHERS YOU SHALL INHERIT — 26:52-56 RESTATED TO THE PEOPLE, THE VERB\'S NUMBER SWITCHING INSIDE THE VERSE. {HP(33, 54, (("והתנחלתם", "את", "הארץ", "בגורל", "למשפחתיכם"), "YOU SHALL TAKE THE LAND AS INHERITANCE BY LOT according to your families — the opening verb Leviticus 25:46\'s (the slaves held as a possession) and this; \'by lot\' four Torah seats (26:55, this, 34:13, 36:2) (computed); the store glosses the lot \'in-pebble\'"), (("לרב", "תרבו", "את", "נחלתו"), "TO THE MANY YOU [ALL] SHALL INCREASE HIS INHERITANCE — 26:54\'s clause with the verb turned PLURAL and the object marker added (26:54 \'you shall increase\', singular, to Moses) (computed on the morphology)"), (("ולמעט", "תמעיט", "את", "נחלתו"), "and to the few YOU SHALL DIMINISH his inheritance — the second verb left SINGULAR in both verses: the number switches inside 33:54 itself (computed)"), (("אל", "אשר", "יצא", "לו", "שמה", "הגורל"), "TO WHOM THE LOT GOES OUT — one seat; 26:56 \'according to the lot shall his inheritance be divided\'"), (("לו", "יהיה", "למטות", "אבתיכם", "תתנחלו"), "his it shall be; BY THE TRIBES OF YOUR FATHERS you shall inherit — one seat (26:55 \'the tribes of their fathers\'); the closing verb 33:54, 34:13, Ezekiel 47:13 (computed)"))} → {AP(33, 54, (("ותחסנון", "ית", "ארעא", "בעדבא", "לזרעיתכון"), "and you shall possess the land BY LOT according to your families — one Aramaic word for the lot at all five seats (26:55, 56; 33:54; 34:13; 36:2) (computed)"), (("לסגיאי", "תסגון", "ית", "אחסנתהון"), "to the many you shall increase their possession — the pair of verbs 26:54\'s own (computed)"), (("ולזעירי", "תזעירון", "ית", "אחסנתהון"), "and to the few you shall diminish their possession — Onkelos makes both verbs plural"), (("לדיפוק", "ליה", "תמן", "עדבא", "די", "ליה", "יהי"), "to whom the lot goes out there, his it shall be"), (("לשבטי", "אבהתכון", "תחסנון"), "by the tribes of your fathers you shall possess"))}.')
row(33, 55, 'MATERIAL', f'AND IF YOU DO NOT DRIVE OUT THE INHABITANTS OF THE LAND FROM BEFORE YOU, THOSE YOU LEAVE OVER SHALL BE THORNS IN YOUR EYES AND PRICKS IN YOUR SIDES, AND THEY SHALL HARASS YOU ON THE LAND WHERE YOU DWELL — THE NEGATIVE ARM, RUN BACK BY JOSHUA 23:13 REVERSED; ONKELOS READS THE FIGURE AS ARMED BANDS. {HP(33, 55, (("ואם", "לא", "תורישו", "את", "ישבי", "הארץ", "מפניכם"), "AND IF YOU DO NOT DRIVE OUT the inhabitants of the land from before you — the verb\'s form one seat (computed)"), (("והיה", "אשר", "תותירו", "מהם"), "those you LEAVE OVER of them — the verb\'s three Torah seats: the Passover\'s \'you shall leave none of it until morning\' (Exodus 12:10), Leviticus 22:30, this (computed); the store glosses \'jut-over\'"), (("לשכים", "בעיניכם", "ולצנינם", "בצדיכם"), "shall be THORNS IN YOUR EYES AND PRICKS IN YOUR SIDES — \'thorns\' one seat; \'pricks\' and \'in your sides\' each two, the other Joshua 23:13, which runs the pair back REVERSED (\'scourges in your sides and pricks in your eyes\'); Judges 2:3 \'they shall be to you for sides\' (computed)"), (("וצררו", "אתכם", "על", "הארץ"), "AND THEY SHALL HARASS YOU on the land — the form\'s one seat; 25:18\'s \'they harass you\' Midian\'s (computed); the store glosses \'and-cramp\'"), (("אשר", "אתם", "ישבים", "בה"), "where you dwell"))} → {AP(33, 55, (("ואם", "לא", "תתרכון", "ית", "יתבי", "ארעא"), "and if you do not drive out the inhabitants of the land"), (("ויהי", "די", "תשארון", "מנהון"), "those you leave of them shall be"), (("לסיען", "נטלן", "זין", "לקבליכון"), "BANDS TAKING UP ARMS AGAINST YOU — the thorns in the eyes read as their referent, one seat in Onkelos Numbers (computed)"), (("ולמשרין", "מקפנכון"), "AND CAMPS SURROUNDING YOU — the pricks in the sides"), (("ויעיקון", "לכון", "על", "ארעא"), "and they shall press you on the land"))}.')
row(33, 56, 'MATERIAL', f'AND IT SHALL BE THAT AS I THOUGHT TO DO TO THEM, I WILL DO TO YOU — THE ARM\'S OUTCOME IN ONE CLAUSE. {HP(33, 56, (("והיה", "כאשר", "דמיתי", "לעשות", "להם"), "and it shall be, AS I THOUGHT TO DO TO THEM — \'as I thought\' Isaiah 14:24\'s oath against Assyria (\'as I have thought, so shall it be\') and this, the phrase\'s two seats (computed); the store glosses \'compare\'"), (("אעשה", "לכם"), "I will do to you"))} → {AP(33, 56, (("ויהי", "כמא", "די", "חשבית", "למעבד", "להון"), "and it shall be, as I PLANNED to do to them — one seat of the word in Onkelos Numbers (computed)"), (("אעבד", "לכון"), "I will do to you"))}.')
